const int enablePin = 9; // PWM Speed Control
const int in1Pin = 8;    // Direction Leg A
const int in2Pin = 7;    // Direction Leg B

void driveMotor(int speed, bool forward) {
  digitalWrite(in1Pin, forward ? HIGH : LOW);
  digitalWrite(in2Pin, forward ? LOW : HIGH);
  analogWrite(enablePin, constrain(speed, 0, 255));
}

void stopMotor() {
  digitalWrite(in1Pin, LOW);
  digitalWrite(in2Pin, LOW);
  analogWrite(enablePin, 0);
}

void setup() {
  pinMode(enablePin, OUTPUT);
  pinMode(in1Pin, OUTPUT);
  pinMode(in2Pin, OUTPUT);
}

void loop() {
  driveMotor(200, true);  // Forward ~78% speed
  delay(2000);
  stopMotor();
  delay(1000);
  driveMotor(200, false); // Reverse
  delay(2000);
  stopMotor();
  delay(1000);
}
```
